from pathlib import Path
import shutil
import py_compile
ROOT=Path(__file__).resolve().parent
APP=ROOT/'backend'/'app.py'
INDEX=ROOT/'index.html'
MODULE=ROOT/'backend'/'studio_inspect_regions_v2.py'
if not (APP.exists() and INDEX.exists()):
    raise SystemExit('Place this patch alongside START_CIRCUIT_STUDIO.bat in the existing CIRCUIT_STUDIO folder.')
MODULE_TEXT='"""Circuit Studio: conservative component region proposals for image inspection.\nNo OCR, object recognition model, pin identity, or continuity measurement is claimed.\n"""\nimport io\nimport base64\nfrom fastapi import APIRouter, UploadFile, File, HTTPException\nfrom PIL import Image, ImageOps\n\nrouter = APIRouter(prefix=\'/api/inspect-regions\', tags=[\'inspect-regions\'])\nMAX_BYTES = 8 * 1024 * 1024\n\ndef find_regions(image):\n    import numpy as np\n    import cv2\n    image = ImageOps.exif_transpose(image).convert(\'RGB\')\n    image.thumbnail((1000, 1000))\n    arr = cv2.cvtColor(np.array(image), cv2.COLOR_RGB2BGR)\n    h, w = arr.shape[:2]\n    gray = cv2.cvtColor(arr, cv2.COLOR_BGR2GRAY)\n    # Rectangular textured regions give *candidate* locations only.\n    enhanced = cv2.createCLAHE(clipLimit=2.0, tileGridSize=(8,8)).apply(gray)\n    edges = cv2.Canny(enhanced, 60, 140)\n    edges = cv2.morphologyEx(edges, cv2.MORPH_CLOSE, cv2.getStructuringElement(cv2.MORPH_RECT, (7,7)))\n    contours, _ = cv2.findContours(edges, cv2.RETR_LIST, cv2.CHAIN_APPROX_SIMPLE)\n    min_area = w*h*0.006\n    candidates=[]\n    for c in contours:\n        x,y,bw,bh=cv2.boundingRect(c)\n        area=bw*bh\n        if area<min_area or area>w*h*.39:continue\n        if bw<30 or bh<20:continue\n        aspect=bw/max(bh,1)\n        if not .30<aspect<4.5:continue\n        perimeter=cv2.arcLength(c,True)\n        if perimeter<1:continue\n        extent=cv2.contourArea(c)/area\n        if extent<.22:continue\n        if x<=2 or y<=2 or x+bw>=w-2 or y+bh>=h-2:continue\n        # Suppress candidates wholly enclosed by larger regions once sorted.\n        candidates.append((int(x),int(y),int(bw),int(bh),float(extent)))\n    candidates.sort(key=lambda b:b[2]*b[3],reverse=True)\n    selected=[]\n    for x,y,bw,bh,extent in candidates:\n        center=(x+bw/2,y+bh/2)\n        if any(x>=a and y>=b and x+bw<=a+aw and y+bh<=b+ah for a,b,aw,ah,_ in selected):continue\n        if any(abs(center[0]-(a+aw/2))<.12*w and abs(center[1]-(b+ah/2))<.12*h and abs(bw*bh-aw*ah)<.08*w*h for a,b,aw,ah,_ in selected): continue\n        selected.append((x,y,bw,bh,extent))\n        if len(selected)>=10:break\n    regions=[{\'id\':\'region-\'+str(i+1),\'x\':round(x/w,4),\'y\':round(y/h,4),\n              \'width\':round(bw/w,4),\'height\':round(bh/h,4),\'label\':\'unidentified region\',\n              \'confidence\':\'unclassified\'} for i,(x,y,bw,bh,_) in enumerate(selected)]\n    return {\'status\':\'regions_proposed\',\'regions\':regions,\'preview_width\':w,\'preview_height\':h,\n      \'message\':str(len(regions))+\' possible rectangular regions. These are not recognized components or verified wire endpoints.\',\n      \'capabilities\':[\'candidate region proposals\',\'manual component labels\',\'manual endpoint trace against current plan\'],\n      \'limitations\':\'A rectangular region can be a breadboard, package, or background shape. Module type, GPIO, wire continuity and electrical correctness are not automatically determined.\'}\n\n@router.post(\'/analyze\')\nasync def analyze(file:UploadFile=File(...)):\n    if file.content_type not in (\'image/png\',\'image/jpeg\',\'image/webp\',\'image/jpg\'):\n        raise HTTPException(415, \'Choose PNG, JPG, or WEBP.\')\n    content=await file.read(MAX_BYTES+1)\n    if len(content)>MAX_BYTES:raise HTTPException(413,\'Image larger than 8 MB\')\n    try:\n        im=Image.open(io.BytesIO(content))\n        if im.width*im.height>24_000_000:raise HTTPException(413,\'Image too large\')\n        im.load()\n        return find_regions(im)\n    except (ValueError,OSError) as exc:\n        raise HTTPException(415,\'Could not decode image\') from exc\n'
UI_SCRIPT='<script id="CS_INSPECT_COMPONENT_ENDPOINTS_V2">\n(()=>{\n\'use strict\';\nconst picker=document.getElementById(\'photofile\');if(!picker)return;\nconst esc=s=>String(s??\'\').replace(/[&<>"\']/g,c=>({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\',"\'":\'&#39;\'}[c]));\nconst root=document.createElement(\'section\');root.id=\'cs-inspect-v2\';root.style.cssText=\'margin:16px 0;border:1px solid #b5aa94;background:#f4f0e6;padding:17px;line-height:1.5;color:#24231f\';\nroot.innerHTML=`<h3 style="margin:0 0 8px">Identify components & trace endpoints</h3><p style="margin:0 0 8px">The photo analyzer proposes regions; you confirm component names and where wires end. Observations are compared with the current Plan. No electrical continuity is measured.</p><div id="cs-v2-status">Choose a circuit photograph to begin.</div><div style="position:relative;max-width:100%;margin:12px 0;display:inline-block" id="cs-v2-frame"><img id="cs-v2-image" alt="Uploaded circuit photo" style="display:none;max-width:100%;max-height:670px;height:auto"><svg id="cs-v2-svg" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1000 1000" preserveAspectRatio="none" style="display:none;position:absolute;inset:0;width:100%;height:100%;pointer-events:none"></svg></div><div id="cs-v2-regions"></div><div style="margin-top:14px;padding-top:10px;border-top:1px solid #bbb"><strong>Trace against the saved Plan</strong><p style="font-size:13px">Select one planned connection and mark its two visible endpoints on the picture. Select an observed destination from the dropdown; the comparison uses <em>your observations</em>, not automatic pin recognition.</p><label>Planned connection <select id="cs-v2-wire" style="max-width:100%;padding:7px"></select></label><label style="display:block;margin-top:8px">Observed ESP32 connection <select id="cs-v2-observed" style="padding:7px"><option value="">Cannot tell / obscured</option><option>3V3</option><option>GND</option><option>GPIO21</option><option>GPIO22</option><option>GPIO25</option><option>GPIO26</option><option>GPIO18</option><option>GPIO19</option><option>5V</option></select></label><div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:10px"><button type="button" id="cs-v2-trace">Mark two visible endpoints</button><button type="button" id="cs-v2-unknown">Mark connection unclear</button><button type="button" id="cs-v2-reset">Clear annotations for photo</button></div><p id="cs-v2-hint" style="font-size:13px"></p><div id="cs-v2-findings"></div></div>`;\nconst other=document.getElementById(\'cs-vision-panel\');if(other)other.insertAdjacentElement(\'afterend\',root);else picker.parentElement.insertAdjacentElement(\'afterend\',root);\nconst $=id=>root.querySelector(\'#\'+id);const img=$(\'cs-v2-image\'),svg=$(\'cs-v2-svg\');let regions=[],items=[],points=[],tracing=false,projectKey=\'\',photoUrl=\'\',chosenLabels={};\nconst readPlan=()=>{try{return JSON.parse(localStorage.getItem(\'circuitstudio-plan-v5\')||\'null\')}catch{return null}};\nfunction planWires(){const plan=readPlan();return (plan?.wiring||[]).filter(w=>w.component&&w.pin&&w.to).map((w,i)=>({id:String(w.id??i),component:String(w.component),pin:String(w.pin),to:String(w.to)}))}\nfunction keyForPlan(){const p=planWires();return \'cs-inspect-v2:\'+p.map(w=>`${w.component}.${w.pin}:${w.to}`).join(\'|\').slice(0,1000)}\nfunction paint(){svg.innerHTML=\'\';const add=(tag,attrs)=>{const el=document.createElementNS(\'http://www.w3.org/2000/svg\',tag);Object.entries(attrs).forEach(([k,v])=>el.setAttribute(k,v));svg.appendChild(el);return el};\nfor(const r of regions){add(\'rect\',{x:r.x*1000,y:r.y*1000,width:r.width*1000,height:r.height*1000,fill:\'none\',stroke:\'#f2a900\',\'stroke-width\':\'3\',\'stroke-dasharray\':\'8 6\'});add(\'text\',{x:r.x*1000+4,y:r.y*1000+15,fill:\'#f2a900\',\'font-size\':\'18\',\'font-weight\':\'bold\'}).textContent=chosenLabels[r.id]||\'?\'}\nfor(const t of items){if(t.points?.length===2){let a=t.points[0],b=t.points[1];add(\'path\',{d:`M${a[0]*1000} ${a[1]*1000} L${b[0]*1000} ${b[1]*1000}`,fill:\'none\',stroke:t.comparison===\'mismatch\'?\'#d43b2f\':\'#22aa92\',\'stroke-width\':4,\'stroke-dasharray\':\'10 7\'});for(const p of t.points)add(\'circle\',{cx:p[0]*1000,cy:p[1]*1000,r:6,fill:\'#ffcb23\',stroke:\'#171717\',\'stroke-width\':2})}}\nfor(const p of points)add(\'circle\',{cx:p[0]*1000,cy:p[1]*1000,r:7,fill:\'#f44336\',stroke:\'white\',\'stroke-width\':2});}\nfunction save(){if(!projectKey)return;try{localStorage.setItem(projectKey,JSON.stringify({items,chosenLabels}))}catch{}}\nfunction findings(){let matched=items.filter(t=>t.comparison===\'matches\').length,bad=items.filter(t=>t.comparison===\'mismatch\').length;let missing=items.filter(t=>t.comparison===\'unknown\').length;let out=`<p><strong>${matched} manually matched</strong> · ${bad} manually reported mismatch${bad===1?\'\':\'es\'} · ${missing} unclear · 0 electrically verified</p>`;\nout+=items.map(t=>`<p style="font-size:13px;border-top:1px solid #d5cbbb;padding:5px 0"><strong>${esc(t.component)} ${esc(t.pin)}</strong> → planned ${esc(t.to)}; observed ${esc(t.observed||\'unknown\')}. ${t.comparison===\'mismatch\'?\'<strong style="color:#a22">Potential mismatch — confirm pin labels in person</strong>\':t.comparison===\'matches\'?\'Matches the declared pin (manual observation only)\':\'Needs a clearer photograph or physical check\'}</p>`).join(\'\');$(\'cs-v2-findings\').innerHTML=out;}\nfunction renderRegions(){let labels=[\'Unidentified\',\'ESP32\',\'MPU6050\',\'OLED\',\'Buzzer\',\'Button\',\'Breadboard\',\'Other\'];$(\'cs-v2-regions\').innerHTML=regions.length?`<strong>${regions.length} possible rectangular areas</strong><p style="font-size:12px">These are unclassified shapes, not automatically recognized devices. Assign labels only where confident.</p>`+regions.map(r=>`<label style="display:inline-block;margin:4px 10px 4px 0">Area ${esc(r.id)} <select data-region="${esc(r.id)}">${labels.map(l=>`<option value="${esc(l)}" ${chosenLabels[r.id]===l?\'selected\':\'\'}>${esc(l)}</option>`).join(\'\')}</select></label>`).join(\'\'):\'No reliable rectangular component regions were proposed; you can still mark visible wire endpoints below.\';\n$(\'cs-v2-regions\').querySelectorAll(\'select[data-region]\').forEach(sel=>sel.addEventListener(\'change\',()=>{chosenLabels[sel.dataset.region]=sel.value;save();paint()}));}\nfunction refreshWires(){const wires=planWires();$(\'cs-v2-wire\').innerHTML=wires.length?wires.map(w=>`<option value="${esc(w.id)}">${esc(w.component)} ${esc(w.pin)} → ${esc(w.to)}</option>`).join(\'\'):\'<option value="">Generate a Plan first</option>\';projectKey=keyForPlan();return wires;}\nfunction capturePoint(e){if(!tracing||img.style.display===\'none\')return;const b=img.getBoundingClientRect();const x=(e.clientX-b.left)/b.width,y=(e.clientY-b.top)/b.height;if(x<0||x>1||y<0||y>1)return;points.push([+x.toFixed(4),+y.toFixed(4)]);paint();if(points.length<2){$(\'cs-v2-hint\').textContent=\'Now click the other visible endpoint.\';return}tracing=false;img.style.cursor=\'default\';const wires=planWires(),wire=wires.find(w=>w.id===$(\'cs-v2-wire\').value),observed=$(\'cs-v2-observed\').value;if(!wire)return;const comparison=!observed?\'unknown\':observed.toLowerCase()===wire.to.toLowerCase()?\'matches\':\'mismatch\';items=items.filter(t=>t.id!==wire.id);items.push({...wire,observed,comparison,points:[...points]});points=[];save();paint();findings();$(\'cs-v2-hint\').textContent=\'Saved as manual observation — not automatic electrical verification.\';}\nimg.addEventListener(\'click\',capturePoint);$(\'cs-v2-trace\').addEventListener(\'click\',()=>{if(!img.src)return;$(\'cs-v2-hint\').textContent=\'Click the first visible endpoint, then the second. This does not automatically identify them.\';refreshWires();points=[];tracing=true;img.style.cursor=\'crosshair\'});\n$(\'cs-v2-unknown\').addEventListener(\'click\',()=>{let wire=planWires().find(w=>w.id===$(\'cs-v2-wire\').value);if(!wire)return;items=items.filter(t=>t.id!==wire.id);items.push({...wire,observed:\'\',comparison:\'unknown\',points:[]});save();paint();findings()});\n$(\'cs-v2-reset\').addEventListener(\'click\',()=>{if(!confirm(\'Clear manual observations for the current photo?\'))return;items=[];chosenLabels={};points=[];save();paint();findings();renderRegions()});\nlet runId=0;picker.addEventListener(\'change\',async()=>{const file=picker.files?.[0];if(!file)return;const seq=++runId;regions=[];items=[];chosenLabels={};points=[];refreshWires();const oldUrl=photoUrl;photoUrl=URL.createObjectURL(file);img.onload=()=>{svg.style.display=\'block\';svg.setAttribute(\'viewBox\',`0 0 1000 1000`);};img.src=photoUrl;img.style.display=\'block\';if(oldUrl)URL.revokeObjectURL(oldUrl);$(\'cs-v2-status\').textContent=\'Finding potential component regions…\';const form=new FormData();form.append(\'file\',file);try{const res=await fetch(\'/api/inspect-regions/analyze\',{method:\'POST\',body:form});if(!res.ok)throw Error(\'HTTP \'+res.status);const data=await res.json();if(seq!==runId)return;regions=data.regions||[];$(\'cs-v2-status\').textContent=data.message+\' Confirm region names and trace visible endpoints manually.\';}catch(e){if(seq!==runId)return;$(\'cs-v2-status\').textContent=\'Region proposal unavailable (\'+e.message+\'). Manual endpoint tracing remains available.\';}renderRegions();paint();findings();});\nrefreshWires();\n})();\n</script>'
if not MODULE.exists() or MODULE.read_text(encoding='utf-8')!=MODULE_TEXT:
    if MODULE.exists():shutil.copy2(MODULE,str(MODULE)+'.before_inspect_regions_v2.bak')
    MODULE.write_text(MODULE_TEXT,encoding='utf-8')
py_compile.compile(str(MODULE),doraise=True)
app=APP.read_text(encoding='utf-8')
route='from backend.studio_inspect_regions_v2 import router as cs_inspect_regions_router\napp.include_router(cs_inspect_regions_router)'
route=route.replace('\\n','\n')
if 'cs_inspect_regions_router' not in app:
    shutil.copy2(APP,str(APP)+'.before_inspect_regions_v2.bak')
    APP.write_text(app.rstrip()+'\n'+route+'\n',encoding='utf-8')
html=INDEX.read_text(encoding='utf-8')
if 'CS_INSPECT_COMPONENT_ENDPOINTS_V2' not in html:
    if '</body>' not in html:raise SystemExit('Expected </body> in index.html. No UI changes made.')
    shutil.copy2(INDEX,str(INDEX)+'.before_inspect_regions_v2.bak')
    INDEX.write_text(html.replace('</body>',UI_SCRIPT+'\n</body>'),encoding='utf-8')
print('Inspect region proposals and photo-to-plan endpoint marking installed. Plan, Wire and firmware unchanged.')
print('Restart START_CIRCUIT_STUDIO.bat; refresh Chrome with Ctrl+Shift+R.')
print('IMPORTANT: identification, endpoint tracing and mismatch labels still require human confirmation.')
